# -*- coding: utf-8 -*-
# Daily-checks terms.
GLOSSARY_ADD = [
    {"term": "Pause point", "defn": "A pause point is a time that has a name, at which you do a short checklist, for example lights-on, the first irrigation or pre-dark. A pause point replaces one long sheet that you do at random times.", "tags": ["operations"]},
    {"term": "Killer item", "defn": "A killer item is a check that is easy to ignore and dangerous if you do not do it. For example, it can be the dehumidification at lights-off or a dosing pump with no irrigation timeout. A checklist must make this small number of items mandatory.", "tags": ["operations"]},
    {"term": "Read-do vs do-confirm", "defn": "Read-do and do-confirm are the two types of checklist. In a read-do checklist, you do each step when you read it, for example for setup or calibration. In a do-confirm checklist, you do the tasks without the checklist, then you stop and make sure that you did all the important items.", "tags": ["operations"]},
    {"term": "Pencil-whipping", "defn": "Pencil-whipping is the record of a check as done when the person did not do the check. It is the usual result when a check is too slow, when no person has the task, or when no person uses the result. It is not only because a person is not careful.", "tags": ["operations"]},
    {"term": "Implementation intention", "defn": "An implementation intention is an if-then instruction that attaches a task to a specified time and location. For example, at lights-on the AM technician does X. It makes the person do the task 2 to 3 times more frequently.", "tags": ["operations"]},
    {"term": "Action limit", "defn": "An action limit is a value that you set before. When a reading is on the incorrect side of this value, a specified procedure is mandatory, and you must write the corrective action. An alert limit is a weaker limit that gives only an indication.", "tags": ["operations", "precision"]},
    {"term": "Auto-tick (self-completing check)", "defn": "An auto-tick is a check item that the system records as done automatically, when its telemetry shows that the condition is correct. Thus the person does only the items that a sensor cannot examine.", "tags": ["operations", "precision"]},
]
